<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientUserinfoEncryptedResponseEncAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientUserinfoEncryptedResponseEncAccessor trait.
 *
 * Covers null default, string/VO assignment via withUserinfoEncryptedResponseEnc,
 * getUserinfoEncryptedResponseEnc/userinfoEncryptedResponseEnc accessors, and isUserinfoEncryptedResponseEncChanged with/without original.
 */
class TrustedClientUserinfoEncryptedResponseEncAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUserinfoEncryptedResponseEnc creates a new instance with the UserinfoEncryptedResponseEnc set
     * from a string value, and getUserinfoEncryptedResponseEnc returns the primitive string.
     */
    public function testWithUserinfoEncryptedResponseEncFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientUserinfoEncryptedResponseEncAccessorUnitTest();

        // Act
        $result = $holder->withUserinfoEncryptedResponseEnc('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getUserinfoEncryptedResponseEnc());
    }
    /**
     * Asserts that withuserinfoEncryptedResponseEnc has access to the value object
     * from a string value, and getUserinfoEncryptedResponseEnc returns the primitive string.
     */
    public function testWithUserinfoEncryptedResponseEncFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientUserinfoEncryptedResponseEncAccessorUnitTest();

        // Act
        $result = $holder->withUserinfoEncryptedResponseEnc('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->userinfoEncryptedResponseEnc()->value());
    }
    public function testChangedUserinfoEncryptedResponseEnc(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientUserinfoEncryptedResponseEncAccessorUnitTest();
        $original = $holder->withUserinfoEncryptedResponseEnc('one');
        $same = $holder->withUserinfoEncryptedResponseEnc('one');
        $modified = $holder->withUserinfoEncryptedResponseEnc('other');

        // Act
        $unchanged = $holder->isUserinfoEncryptedResponseEncChanged();
        $withSame = $original->isUserinfoEncryptedResponseEncChanged($same);
        $withDiferent = $original->isUserinfoEncryptedResponseEncChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientUserinfoEncryptedResponseEncAccessorUnitTest
{
    use TrustedClientUserinfoEncryptedResponseEncAccessor;
}
